Q = [
    make(1, "人體生殖系統的主要功能，哪項最完整？", {"A": "產生配子、分泌相關激素，並提供有性生殖所需的構造", "B": "只負責把尿液由腎臟送到膀胱", "C": "把食物分解成葡萄糖並送入血液", "D": "直接製造所有體細胞的遺傳物質"}, "生殖系統能產生精子或卵等配子，也能分泌相關激素；泌尿、消化與一般體細胞更新是其他功能。", "先分辨題目問的是生殖系統還是相鄰的泌尿、消化系統，再列出配子與激素兩個核心功能。", ["圈出『生殖系統』與『主要功能』。", "確認配子是生殖系統的重要產物。", "補上生殖腺分泌激素的功能。", "排除尿液、消化與一般體細胞製造的敘述。", "所以選 A。"], "easy"),
    make(2, "配子與一般體細胞相比，最重要的差異為何？", {"A": "配子通常具有單套染色體，受精時兩個配子結合可恢復雙套", "B": "配子一定比體細胞大，而且沒有細胞核", "C": "配子具有三套染色體，才能形成正常受精卵", "D": "配子只能由有絲分裂產生，與生殖無關"}, "精子與卵等配子通常為單套染色體，精卵結合後形成的受精卵恢復雙套，這有助於維持物種染色體套數。", "染色體題先比較套數，再連到受精前後的變化，不用外觀大小猜測。", ["先辨認題目比較的是配子與體細胞。", "確認體細胞通常為雙套、配子通常為單套。", "把精卵結合連到受精卵恢復雙套。", "排除三套、無細胞核與有絲分裂直接產生等說法。", "所以選 A。"], "medium"),
    make(3, "下列哪一組配對正確？", {"A": "睪丸—產生精子並分泌男性激素；卵巢—產生卵細胞並分泌女性激素", "B": "子宮—產生精子；睪丸—提供胚胎著床場所", "C": "輸卵管—製造所有卵細胞；陰道—分泌主要消化酵素", "D": "膀胱—產生卵細胞；卵巢—儲存尿液"}, "睪丸是男性生殖腺，可產生精子並分泌男性激素；卵巢是女性生殖腺，可產生卵細胞並分泌女性激素。", "構造功能題採一對一配對，先找生殖腺，再排除把生殖器官與泌尿、消化功能混淆的選項。", ["找出男性與女性的生殖腺。", "將睪丸連到精子與男性激素。", "將卵巢連到卵細胞與女性激素。", "排除子宮、輸卵管、膀胱被誤配的功能。", "所以選 A。"], "easy"),
    make(4, "在人類正常有性生殖的路徑中，哪個順序合理？", {"A": "卵巢排出卵細胞→精卵在輸卵管附近相遇→受精卵移向子宮並可能著床", "B": "卵細胞在子宮產生→精卵在膀胱相遇→受精卵回到卵巢", "C": "精子在子宮產生→受精在胃中進行→胚胎進入輸尿管", "D": "卵細胞先在陰道著床→再移到輸卵管完成受精"}, "卵細胞由卵巢排出，精卵通常在輸卵管中相遇形成受精卵，受精卵再向子宮移動並在適當條件下著床。", "順序題先固定產生配子的器官，再依受精位置與胚胎發育場所排序。", ["先確認卵細胞由卵巢排出。", "找出精卵相遇與受精的合理位置是輸卵管。", "把受精卵移向子宮放在受精之後。", "確認著床是子宮內膜事件，排除膀胱、胃與輸尿管。", "所以選 A。"], "medium"),
    make(5, "若卵子未受精，月經週期後段常見的變化為何？", {"A": "相關激素支持下降，子宮內膜剝落而出血，形成月經", "B": "受精卵立刻在輸卵管增厚成胎兒", "C": "黃體會永久增加激素，使子宮內膜不再變化", "D": "卵巢停止所有激素分泌，人體立即停止生長"}, "未受精時，支持子宮內膜的相關激素濃度下降，內膜剝落形成月經；這不是受精卵發育，也不表示所有生長活動停止。", "週期資料題先判定是否受精，再追蹤激素支持與子宮內膜的因果鏈。", ["辨認題目條件是卵子未受精。", "確認沒有持續發育的受精卵與胚胎訊號。", "連結黃體等相關激素支持下降。", "推論子宮內膜剝落並形成月經，排除永久增厚。", "所以選 A。"], "medium"),
    make(6, "下列哪項最能說明激素在生殖系統中的作用方式？", {"A": "由生殖腺等內分泌構造分泌後，隨血液到達標的器官，調節其活動", "B": "只在生殖器官表面流動，不會經由血液運送", "C": "激素就是精子或卵細胞本身，可直接與配子融合", "D": "所有激素都只控制消化道，不會影響生殖功能"}, "激素由內分泌構造分泌，經體液或血液運送到具有受體的標的細胞，調節生殖週期、配子形成或其他生理活動。", "不要把激素當成細胞或器官；用『來源—運輸—標的—調節』四格判斷。", ["找出激素的來源是內分泌構造。", "確認激素可經血液運送。", "找出作用對象是具有相應受體的標的細胞。", "排除激素等同配子與只作用消化道的說法。", "所以選 A。"], "medium"),
    make(7, "為何有性生殖的子代通常不會與任一親代完全相同？", {"A": "子代的遺傳物質來自兩個配子，配子組合與基因排列可造成差異", "B": "受精會把親代所有染色體刪除，只留下環境造成的性狀", "C": "有性生殖完全不涉及遺傳物質，所以差異只靠外觀", "D": "每個子代都必然具有比親代多一套染色體"}, "有性生殖由兩個配子結合，配子各自帶有一套遺傳物質，組合後可能產生不同的遺傳排列，因此子代常與親代或彼此有差異。", "先找差異來源是兩個配子的組合，再排除染色體刪除、無遺傳物質與套數永久增加。", ["確認有性生殖包含配子結合。", "將兩個來源的遺傳物質放入同一受精卵。", "說明不同配子組合可造成子代差異。", "排除遺傳物質消失與染色體套數永久增加。", "所以選 A。"], "easy"),
    make(8, "觀察女性生殖系統圖時，若要判斷受精與著床的位置，哪項說法較合理？", {"A": "受精通常在輸卵管發生；胚胎後續移到子宮內膜著床", "B": "受精一定在子宮內膜完成，著床則在卵巢表面完成", "C": "受精在膀胱完成，著床在尿道完成", "D": "受精與著床都只發生在陰道內"}, "人類精卵通常在輸卵管相遇形成受精卵，胚胎再移動到子宮，著床於子宮內膜；這兩個事件的位置不同。", "圖判讀先把『相遇形成受精卵』與『附著發育』分成兩個事件。", ["先辨認受精是精卵相遇的事件。", "將受精位置放在輸卵管。", "確認著床是胚胎附著子宮內膜的事件。", "排除卵巢、膀胱、尿道與陰道的錯誤位置。", "所以選 A。"], "medium"),
    make(9, "有人宣稱『只要月經延遲，就能確定已經懷孕』。哪項回應最符合證據推理？", {"A": "不能只靠單一現象確定；月經延遲有多種可能，應使用適當檢測並依專業建議判讀", "B": "一定正確，月經週期不可能受壓力、疾病或其他因素影響", "C": "一定錯誤，懷孕永遠不會改變月經週期", "D": "只要觀察腹部外觀，就能直接確認受精與著床"}, "月經延遲可能有多種原因，單一現象不足以證明受精或著床；需使用適當檢測並由合格醫療專業協助解釋。", "健康宣稱題先區分觀察與診斷，再檢查證據是否足以支持唯一結論。", ["標記已觀察到的現象只有月經延遲。", "列出可能影響週期的其他因素。", "確認不能把單一現象直接等同受精與著床。", "提出適當檢測與專業判讀作為更強證據。", "所以選 A。"], "hard"),
    make(10, "要用模型說明生殖系統、配子與激素如何合作，哪項紀錄最完整？", {"A": "標出配子來源與套數、受精前後的染色體變化、相關激素作用及事件順序", "B": "只畫男性或女性其中一個器官，不標示配子", "C": "只記錄外觀變化，不區分受精、著床與激素", "D": "把所有生殖事件都標成同一時間、同一器官發生"}, "完整模型要同時交代生殖腺產生配子、配子套數、受精恢復套數、激素調節與受精到著床的順序；只畫器官或只記外觀無法解釋機制。", "整合題採『構造—配子—套數—激素—時間線』五欄回查。", ["先標示男性與女性生殖腺及其配子。", "寫出配子通常為單套，受精卵恢復雙套。", "補上激素來源與其調節標的。", "依排卵、受精、移動與著床建立時間線。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
